import logging
import re
from robot.utils.robottypes import is_truthy

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class RadParamHandling(object):

    def change_rad_param(self, name, param, value, is_permanent=True):
        """
        Changes RaD parameter online through AaShell permanently

        :param str name: alias name
        :param str param: parameter to change in hex format (0x###)
        :param str value: value of parameter
        :param bool is_permanent: is parameter change done permanently
        """
        if not re.match(r'0x[a-fA-F0-9]+', param):
            raise Exception('Given parameter not in proper hex format')
        self._assert_command_available_in_help(name, "help", "rad")
        output = self.execute_aashell_command(
            name=name,
            command='rad -m{change_type}w {param} {value}'.format(
                change_type='p' if is_permanent else 'o',
                param=param,
                value=value))
        if 'written succesfully' not in output:
            raise Exception("RaD parameter change was unsuccessful: " + output)

    def change_rad_params(self, name, params, is_permanent=True):
        """
        Changes RaD parameter online through AaShell permanently

        :param str name: alias name
        :param list params: list of RaD parameters with value to change in format [Param1, Value1, Param2, Value2, ...]
        :param bool is_permanent: is parameter change done permanently
        """
        params_list = [] or iter(params)
        logger.info('Changing given R&D flags with Values:{}'.format(params))
        for rnd_param in params_list:
            self.change_rad_param(name, param=rnd_param, value=next(params_list), is_permanent=is_truthy(is_permanent))

    def enable_rad_params_in_runtime(self, name, params=None):
        """
        Sets RaD parameters to True from params list online through AaShell

        :param str name: alias name
        :param list params: list of RaD parameters to change in format [0x#####a, 0x#####b, ...]
        """
        params_list = [] or params
        logger.info('Enabling given R&D flags:{}'.format(params_list))
        for rnd_param in params_list:
            self.change_rad_param(name, param=rnd_param, value='1', is_permanent=False)

    def disable_rad_params_in_runtime(self, name, params=None):
        """
        Sets RaD parameters to False from params list online through AaShell

        :param str name: alias name
        :param list params: list of RaD parameters to change in format [0x#####a, 0x#####b, ...]
        """
        params_list = [] or params
        logger.info('Disabling given R&D flags:{}'.format(params_list))
        for rnd_param in params_list:
            self.change_rad_param(name, param=rnd_param, value='0', is_permanent=False)
